{"content": "#!/usr/bin/env python3
"""Retry failed VNDB searches with different names."""
import json, urllib.request, time, sys

API = "https://api.vndb.org/kana/vn"
HEADERS = {"Content-Type": "application/json", "Accept": "application/json"}

# Failed ones: try alternative search terms
searches = [
    (3, ["终之Stella", "Tsui no Stella", "终のステラ", "Stella", "Key"]),
    (7, ["白昼梦", "白日梦的青写真", "白日梦", "白昼梦の青写真", "Laplacian"]),
    (13, ["星空铁道", "星空鉄道とシロの旅", "Shiro no Tabi", "白", "しらたま"]),
]

for local_id, terms in searches:
    print(f"\n--- G({local_id}) ---")
    found = False
    for term in terms:
        if found:
            break
        payload = {
            "filters": ["search", "=", term],
            "fields": "id,image.url,image.dims,title",
            "results": 5
        }
        try:
            req = urllib.request.Request(API, data=json.dumps(payload).encode(), headers=HEADERS, method="POST")
            with urllib.request.urlopen(req, timeout=15) as resp:
                data = json.loads(resp.read())
            items = data.get("results", [])
            if items:
                print(f"  Term '{term}': {len(items)} results")
                for item in items:
                    vid = item.get("id", "?")
                    title = item.get("title", "?")
                    img = (item.get("image") or {}).get("url", "no cover")
                    print(f"    {vid} → {title} → {img}")
