    24: "https://t.vndb.org/cv/55/79855.jpg",
    30: "https://t.vndb.org/cv/46/80746.jpg",
    31: "https://t.vndb.org/cv/78/90878.jpg",
    33: "https://t.vndb.org/cv/17/90017.jpg",
}

def download(url):
    try:
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=60) as r:
            data = r.read()
            return (url, data, True)
    except Exception as e:
        return (url, None, False)

import base64
results = {}
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
    futures = {executor.submit(download, url): gid for gid, url in covers.items()}
    for future in concurrent.futures.as_completed(futures):
        gid = futures[future]
        url, data, ok = future.result()
        if ok:
            b64 = base64.b64encode(data).decode()
            results[gid] = f"data:image/jpeg;base64,{b64}"
            print(f"  ✓ G({gid}): {len(data)/1024:.0f}KB -> base64 {len(b64)/1024:.0f}KB")
        else:
            print(f"  ✗ G({gid}): failed")

print(f"\n=== Total base64 size: {sum(len(v) for v in results.values())/1024/1024:.1f}MB ===")
print(f"Downloaded {len(results)}/{len(covers)} covers")
"}

